{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260926T221158Z/cell-ar5AAB/src/address.js","content":"/**
 * Cell-address parsing: decomposing a raw "word" (letters followed by
 * digits) into a column/row pair, deciding whether that pair falls inside
 * the addressable A1..ZZ999 grid, and converting between column letters and
 * their ascending sort index.
 */

// Matches the address form: one or two letters then one to three digits.
const STRICT_ADDRESS = /^[A-Za-z]{1,2}[0-9]{1,3}$/

/** Column letters (1-2 chars) -> ascending index, A=1 ... ZZ=702. */
function columnToIndex(letters) {
  if (letters.length === 1) {
    return letters.charCodeAt(0) - 64
  }
  const first = letters.charCodeAt(0) - 64
  const second = letters.charCodeAt(1) - 64
  return 26 + (first - 1) * 26 + second
}

/** Ascending column index (1..702) -> its column letters. */
function indexToColumn(index) {
  if (index <= 26) {
    return String.fromCharCode(64 + index)
  }
  const rest = index - 26
  const first = Math.floor((rest - 1) / 26) + 1
  const second = ((rest - 1) % 26) + 1
  return String.fromCharCode(64 + first) + String.fromCharCode(64 + second)
}

/**
 * Splits a "word" token (letters followed by digits, case folded already or
 * not) into its column/row parts, and reports whether the result lies
 * inside the addressable grid: 1-2 letters, 1-3 digits, row >= 1.
 */
function decomposeWord(text) {
  const match = /^([A-Za-z]+)([0-9]*)$/.exec(text)
  const colLetters = match[1].toUpperCase()
  const rowDigits = match[2]
  const rowNum = rowDigits === '' ? null : parseInt(rowDigits, 10)
  const addressable =
    colLetters.length >= 1 &&
    colLetters.length <= 2 &&
    rowDigits.length >= 1 &&
    rowDigits.length <= 3 &&
    rowNum >= 1
  return {
    colLetters,
    rowDigits,
    rowNum,
    addressable,
    colIndex: addressable ? columnToIndex(colLetters) : null,
    label: addressable ? colLetters + String(rowNum) : null,
  }
}

/** Whether a raw sheet-line address token is a valid addressable cell. */
function isStrictAddress(token) {
  if (!STRICT_ADDRESS.test(token)) return false
  const match = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(token)
  return parseInt(match[2], 10) >= 1
}

function labelFor(colIndex, rowNum) {
  return indexToColumn(colIndex) + String(rowNum)
}

module.exports = { columnToIndex, indexToColumn, decomposeWord, isStrictAddress, labelFor }
"}

