  }

  next() {
    return this.tokens[this.pos++]
  }

  parseFormula() {
    const node = this.parseComparison()
    if (node === null) return null
    if (this.pos !== this.tokens.length) return null
    return node
  }

  parseComparison() {
    let left = this.parseAdditive()
    if (left === null) return null
    while (this.peek() && COMPARISON_OPS.has(this.peek().type)) {
      const op = this.next().type
      const right = this.parseAdditive()
      if (right === null) return null
      left = { type: 'Binary', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    if (left === null) return null
    while (this.peek() && (this.peek().type === 'PLUS' || this.peek().type === 'MINUS')) {
      const op = this.next().type
      const right = this.parseMultiplicative()
      if (right === null) return null
      left = { type: 'Binary', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    if (left === null) return null
    while (this.peek() && (this.peek().type === 'STAR' || this.peek().type === 'SLASH')) {
      const op = this.next().type
      const right = this.parsePower()
      if (right === null) return null
      left = { type: 'Binary', op, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (left === null) return null
    if (this.peek() && this.peek().type === 'CARET') {
      this.next()
      const right = this.parsePower()
      if (right === null) return null
      return { type: 'Binary', op: 'CARET', left, right }
    }
    return left
  }

  parseUnary() {
    if (this.peek() && (this.peek().type === 'PLUS' || this.peek().type === 'MINUS')) {
      const op = this.next().type
      const operand = this.parseUnary()
      if (operand === null) return null
      return { type: 'Unary', op, operand }
    }
    return this.parsePrimary()
