 * The four value kinds a cell can hold, and the coercions the spec defines
 * between them: reading a value as a number (for arithmetic and the numeric
 * functions) and comparing two values (for the comparison operators).
 */

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

export function numberValue(value) {
  return { type: 'number', value }
}
export function textValue(value) {
  return { type: 'text', value }
}
export function boolValue(value) {
  return { type: 'bool', value }
}
export function errorValue(value) {
  return { type: 'error', value }
}

export const ERR_VALUE = errorValue('#VALUE!')
export const ERR_DIV0 = errorValue('#DIV/0!')
export const ERR_REF = errorValue('#REF!')
export const ERR_ERR = errorValue('#ERR!')
export const ERR_NAME = errorValue('#NAME?')
export const ERR_CYCLE = errorValue('#CYCLE!')

/** Reads a value as a number for an arithmetic position: bool -> 1/0, text -> #VALUE!. */
export function toNumber(value) {
  if (value.type === 'number') return value
  if (value.type === 'bool') return numberValue(value.value ? 1 : 0)
  if (value.type === 'text') return ERR_VALUE
  return value // already an error
}

function rank(value) {
  if (value.type === 'number') return 0
  if (value.type === 'text') return 1
  return 2 // bool
}

/** Three-way compare of two non-error values per the cross-kind ordering rules. */
export function compareValues(l, r) {
  const rl = rank(l)
  const rr = rank(r)
  if (rl !== rr) return rl < rr ? -1 : 1
  if (l.type === 'number') return l.value < r.value ? -1 : l.value > r.value ? 1 : 0
  if (l.type === 'text') return l.value < r.value ? -1 : l.value > r.value ? 1 : 0
  // bool: false below true
  return (l.value ? 1 : 0) - (r.value ? 1 : 0)
}

/** Rounds a finite number to ten significant digits and formats it as JS would. */
export function formatNumber(n) {
  if (n === 0) return '0'
  const rounded = Number(n.toPrecision(10))
  if (rounded === 0) return '0'
  return String(rounded)
}

export function formatValue(value) {
  if (value.type === 'error') return value.value
  if (value.type === 'bool') return value.value ? 'TRUE' : 'FALSE'
  if (value.type === 'text') return value.value
  return formatNumber(value.value)
}
"}

