 * Evaluates cell values. A single memoized, cycle-tracking evaluator backs
 * every cell so formulas can reference each other freely; a cell whose
 * evaluation reaches itself becomes `#CYCLE!`.
 *
 * A range is only expanded into the multiple cells it covers when it is the
 * direct argument of one of the five collecting functions (SUM, MIN, MAX,
 * COUNT, AVG). Anywhere else — bare, parenthesized, or as an argument to ABS
 * or IF — it is "misplaced" and evaluates to `#ERR!`, per the spec.
 */
import { labelFor } from './address.js'
import {
  numberValue,
  boolValue,
  toNumber,
  compareValues,
  ERR_VALUE,
  ERR_DIV0,
  ERR_REF,
  ERR_ERR,
  ERR_NAME,
  ERR_CYCLE,
} from './values.js'

const COLLECTING_FUNCTIONS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'])

export class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.cache = new Map()
    this.stack = new Set()
  }

  /** Evaluates the declared or undeclared cell at (colIndex, rowNum). */
  evaluateCell(colIndex, rowNum) {
    const label = labelFor(colIndex, rowNum)
    if (this.cache.has(label)) return this.cache.get(label)
    if (this.stack.has(label)) return ERR_CYCLE

    this.stack.add(label)
    let result
    const cell = this.cells.get(label)
    if (!cell) {
      result = numberValue(0)
    } else if (cell.kind === 'literal') {
      result = cell.value
    } else if (cell.ast === null) {
      result = ERR_ERR
    } else {
      result = this.evaluate(cell.ast)
    }
    this.stack.delete(label)
    this.cache.set(label, result)
    return result
  }

  /** Evaluates an AST node in a generic (non-collecting) context. */
  evaluate(node) {
    switch (node.type) {
      case 'Number':
        return numberValue(node.value)
      case 'Bool':
        return boolValue(node.value)
      case 'Paren':
        return this.evaluate(node.inner)
      case 'Address':
        return node.addressable ? this.evaluateCell(node.colIndex, node.rowNum) : ERR_REF
      case 'Range':
        return ERR_ERR // a range not directly a function argument is misplaced
      case 'Unary':
        return this.evaluateUnary(node)
      case 'Binary':
        return this.evaluateBinary(node)
      case 'Call':
        return this.evaluateCall(node)
      default:
        throw new Error(`unknown node type: ${node.type}`)
    }
  }

  evaluateUnary(node) {
    const v = this.evaluate(node.operand)
    if (v.type === 'error') return v
    const n = toNumber(v)
    if (n.type === 'error') return n
    const value = node.op === 'MINUS' ? -n.value : n.value
    return Number.isFinite(value) ? numberValue(value) : ERR_DIV0
  }

  evaluateBinary(node) {
    const l = this.evaluate(node.left)
    if (l.type === 'error') return l
    const r = this.evaluate(node.right)
    if (r.type === 'error') return r

    if (node.op === 'PLUS' || node.op === 'MINUS' || node.op === 'STAR' || node.op === 'SLASH' || node.op === 'CARET') {
      const ln = toNumber(l)
      if (ln.type === 'error') return ln
      const rn = toNumber(r)
      if (rn.type === 'error') return rn
      let value
      switch (node.op) {
        case 'PLUS':
          value = ln.value + rn.value
          break
        case 'MINUS':
          value = ln.value - rn.value
          break
        case 'STAR':
          value = ln.value * rn.value
          break
        case 'SLASH':
          value = ln.value / rn.value
          break
        case 'CARET':
          value = Math.pow(ln.value, rn.value)
          break
      }
      return Number.isFinite(value) ? numberValue(value) : ERR_DIV0
    }

    // Comparison
    const cmp = compareValues(l, r)
    switch (node.op) {
      case 'EQ':
        return boolValue(cmp === 0)
      case 'NE':
        return boolValue(cmp !== 0)
      case 'LT':
        return boolValue(cmp < 0)
      case 'LE':
        return boolValue(cmp <= 0)
      case 'GT':
        return boolValue(cmp > 0)
      case 'GE':
        return boolValue(cmp >= 0)
    }
  }

  /** Expands a range argument into the values of the cells it covers. */
  expandRange(node) {
    if (!node.from.addressable || !node.to.addressable) return [ERR_REF]
    const colMin = Math.min(node.from.colIndex, node.to.colIndex)
    const colMax = Math.max(node.from.colIndex, node.to.colIndex)
    const rowMin = Math.min(node.from.rowNum, node.to.rowNum)
    const rowMax = Math.max(node.from.rowNum, node.to.rowNum)
    const values = []
    for (let col = colMin; col <= colMax; col++) {
      for (let row = rowMin; row <= rowMax; row++) {
        values.push(this.evaluateCell(col, row))
      }
    }
    return values
  }

  evaluateCall(node) {
    if (!node.known) return ERR_NAME
    if (!node.arityOk) return ERR_ERR

    if (COLLECTING_FUNCTIONS.has(node.name)) {
      const flat = []
      for (const arg of node.args) {
        if (arg.type === 'Range') {
          flat.push(...this.expandRange(arg))
        } else {
          flat.push(this.evaluate(arg))
        }
      }
      const firstError = flat.find((v) => v.type === 'error')
      if (firstError) return firstError
      return this.reduceCollected(node.name, flat)
    }

    if (node.name === 'ABS') {
      const v = this.evaluate(node.args[0])
      if (v.type === 'error') return v
      const n = toNumber(v)
      if (n.type === 'error') return n
      const value = Math.abs(n.value)
      return Number.isFinite(value) ? numberValue(value) : ERR_DIV0
    }

    if (node.name === 'IF') {
      const condRaw = this.evaluate(node.args[0])
      if (condRaw.type === 'error') return condRaw
      const cond = toNumber(condRaw)
      if (cond.type === 'error') return cond
      const branch = cond.value !== 0 ? node.args[1] : node.args[2]
      return this.evaluate(branch)
    }

    throw new Error(`unhandled function: ${node.name}`)
  }

  reduceCollected(name, flat) {
    if (name === 'COUNT') {
      const count = flat.filter((v) => v.type === 'number').length
      return numberValue(count)
    }

    const numbers = []
    for (const v of flat) {
      const n = toNumber(v)
      if (n.type === 'error') return n
      numbers.push(n.value)
    }

    let value
    if (name === 'SUM') {
      value = numbers.reduce((a, b) => a + b, 0)
    } else if (name === 'MIN') {
      value = Math.min(...numbers)
    } else if (name === 'MAX') {
      value = Math.max(...numbers)
    } else if (name === 'AVG') {
      value = numbers.reduce((a, b) => a + b, 0) / numbers.length
    }
    return Number.isFinite(value) ? numberValue(value) : ERR_DIV0
  }
}
"}

